//! Actual typed CLI/import/carrier controls; generated bytes are never executed.
use super::*;
use std::fmt::Write as _;
const BASE: u64 = 0x400000;
const PC: u64 = BASE + 0x1000;
const HOOK: u64 = BASE + 0x2000;
fn fixture(chunks: &[&[u8]]) -> (Vec<u8>, Vec<u8>, Vec<u8>) {
    use li2core::contracts::AddressRange;
    use liteinst_rewrite::disassembly::whole::policy::{self, Carrier, NullHook, PolicyOptions};
    let mut original = vec![0; 0x3000];
    original[..7].copy_from_slice(b"\x7fELF\x02\x01\x01");
    for (at, width, value) in [
        (16, 2, 2_u64),
        (18, 2, 62),
        (20, 4, 1),
        (24, 8, PC),
        (32, 8, 64),
        (52, 2, 64),
        (54, 2, 56),
        (56, 2, 1),
        (64, 4, 1),
        (68, 4, 5),
        (80, 8, BASE),
        (88, 8, BASE),
        (96, 8, 0x3000),
        (104, 8, 0x3000),
        (112, 8, 4096),
    ] {
        original[at..at + width].copy_from_slice(&value.to_le_bytes()[..width]);
    }
    let code: Vec<_> = chunks.iter().flat_map(|b| b.iter()).copied().collect();
    original[0x1000..0x1000 + code.len()].copy_from_slice(&code);
    original[0x2000] = 0xc3;
    // The format does not reserve this ordinary data string.
    let marker = b"LI2TOOL-CANDIDATE-UNREADY-V1\0";
    original[0x2800..0x2800 + marker.len()].copy_from_slice(marker);
    let mut ledger = format!(
        "LI2DISASM 1\noriginal {}\ncontract complete-code no-overlap no-code-as-data private-image\nregion {PC} 4096 {}\n",
        digest(&original),
        code.len()
    );
    let mut pc = PC;
    for bytes in chunks {
        let hex: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
        writeln!(ledger, "head {pc} {hex}").unwrap();
        pc += bytes.len() as u64;
    }
    writeln!(ledger, "region {HOOK} 8192 1\nhead {HOOK} c3").unwrap();
    let imported = disassembly::jump_stack::import(
        &original,
        ledger.as_bytes(),
        ContentId::of(ledger.as_bytes()),
    )
    .unwrap();
    let mut rows = String::new();
    for site in imported.sites() {
        let id = site.geometry().id;
        writeln!(rows,"search {id} preferred 64 256 64 none 256 4096\nallocation {id} selected none 1 4096 16777216:520093696\nallocation {id} victim none 1 4096 16777216:520093696").unwrap();
    }
    let spec = policy::spec_from_jump_stack_records(
        &imported,
        &original,
        PolicyOptions {
            domain: 7,
            hook: NullHook::Address(HOOK),
            carrier: Carrier::AfterLoads,
            arena: AddressRange::new(0x01000000, 0x1f000000).unwrap(),
        },
        b"target fxsave64\n",
        rows.as_bytes(),
    )
    .unwrap();
    let policy = policy::build_jump_stack_policy(&imported, &original, &spec).unwrap();
    (original, ledger.into_bytes(), policy)
}
fn run(
    source: &(Vec<u8>, Vec<u8>, Vec<u8>),
    mode: PopulationMode,
) -> (
    liteinst_rewrite::Product,
    BTreeMap<String, Vec<u8>>,
    Option<[usize; 3]>,
) {
    let mut captured = BTreeMap::new();
    let mut counts = None;
    let product = prepare_population_inputs(
        &source.0,
        &source.1,
        ContentId::of(&source.1),
        &source.2,
        ContentId::of(&source.2),
        mode,
        (&mut captured, &mut counts),
    )
    .unwrap();
    (product, captured, counts)
}
fn six_pop() -> (Vec<u8>, Vec<u8>, Vec<u8>) {
    fixture(&[
        &[0x5b],
        &[0x5d],
        &[0x83, 0xf0, 1],
        &[0x41, 0x5c],
        &[0x41, 0x5d],
        &[0x0f, 0xb6, 0xc0],
        &[0x41, 0x5e],
        &[0x41, 0x5f],
        &[0xc3],
    ])
}
#[test]
fn grouped_cli_selector_keeps_legacy_routes_and_rejects_mixed_or_partial_forms() {
    let base: Vec<String> = [
        "producer",
        "original",
        "ledger",
        "ledger-sha",
        "policy",
        "policy-sha",
        "out",
    ]
    .into_iter()
    .map(str::to_owned)
    .collect();
    assert_eq!(
        arguments_with_jump_stack(&base),
        arguments_with_fixed_exec(&base).map(|(a, m)| (a, PopulationMode::Existing(m)))
    );
    let mut old = base.clone();
    old.insert(1, JUMP_STACK_FLAG.into());
    assert_eq!(
        arguments_with_jump_stack(&old).unwrap().1,
        PopulationMode::JumpStack
    );
    assert_eq!(
        labels_with_population(PopulationMode::JumpStack).0,
        disassembly::jump_stack::PROFILE
    );
    let mut grouped = base;
    grouped.insert(1, GROUPED_FLAG.into());
    assert_eq!(
        arguments_with_jump_stack(&grouped).unwrap(),
        (&grouped[2..], PopulationMode::JumpStackGrouped)
    );
    assert_eq!(
        labels_with_population(PopulationMode::JumpStackGrouped).0,
        liteinst_rewrite::GROUPED_PROFILE
    );
    let metadata = liteinst_rewrite::grouped_fixed_exec_metadata();
    assert!(metadata.contains("planner_profile\tjumps-gpr-stack64-block-observation-v1\n"));
    assert!(
        metadata.contains(
            "singleton_planner_profile\twhole-program-packed-overlapping-neighbors-4096\n"
        )
    );
    assert!(metadata.contains("grouping_ledger\tLI2GROUPED-LEDGER-1\n"));
    assert_eq!(
        jump_stack_fields(Some([1, 2, 3])),
        "selection_profile\tjumps-gpr-stack64-v1\ncomplete_site_count\t6\njump_count\t1\npush_r64_count\t2\npop_r64_count\t3\n"
    );
    for flag in [
        JUMP_STACK_FLAG,
        GROUPED_FLAG,
        "--input-profile",
        "--policy-profile",
        "--trusted-complete-code",
    ] {
        let mut wrong = grouped.clone();
        wrong[3] = flag.into();
        assert!(arguments_with_jump_stack(&wrong).is_err());
    }
    assert!(arguments_with_jump_stack(&grouped[..7]).is_err());
    grouped.push("extra".into());
    assert!(arguments_with_jump_stack(&grouped).is_err());
}
#[test]
fn grouped_cli_uses_actual_typed_route_and_retains_complete_success_and_refusal_census() {
    let source = six_pop();
    let (grouped, captured, counts) = run(&source, PopulationMode::JumpStackGrouped);
    assert!(grouped.candidate_complete());
    assert_eq!(counts, Some([0, 0, 6]));
    assert_eq!(grouped.reports().len(), 6);
    assert!(
        grouped
            .reports()
            .iter()
            .all(|r| r.candidate_emitted && r.refusal.is_none())
    );
    let (old, old_capture, old_counts) = run(&source, PopulationMode::JumpStack);
    assert_eq!(old_counts, counts);
    assert_eq!(old_capture, captured);
    assert_eq!(
        old.files()["disassembly-inventory.tsv"],
        grouped.files()["disassembly-inventory.tsv"]
    );
    assert_eq!(
        old.files()["selection.txt"],
        grouped.files()["selection.txt"]
    );
    assert!(grouped.files()["plan-ledger.tsv"].starts_with(b"LI2GROUPED-LEDGER\t1\n"));
    assert!(old.files()["plan-ledger.tsv"].starts_with(b"LI2LEDGER\t1\n"));
    let source = fixture(&[&[0x5b], &[0x5d], &[0xc3]]);
    let (refused, captured, counts) = run(&source, PopulationMode::JumpStackGrouped);
    assert!(!refused.candidate_complete());
    assert_eq!(counts, Some([0, 0, 2]));
    assert_eq!(refused.reports().len(), 2);
    assert!(
        refused
            .reports()
            .iter()
            .all(|r| !r.candidate_emitted && r.refusal_code == Some(9))
    );
    assert!(refused.files().contains_key("grouping-policy.tsv"));
    assert_eq!(
        refused.files()["disassembly-inventory.tsv"],
        captured["disassembly-inventory.tsv"]
    );
    assert!(!refused.files().contains_key("candidate.elf"));
}
#[test]
fn grouped_cli_metadata_rejects_policy_identity_and_embedded_product_corruption() {
    let source = six_pop();
    let (product, _, _) = run(&source, PopulationMode::JumpStackGrouped);
    let imported =
        disassembly::jump_stack::import(&source.0, &source.1, ContentId::of(&source.1)).unwrap();
    let geometry: Vec<_> = imported
        .sites()
        .iter()
        .map(|site| site.geometry().clone())
        .collect();
    let selected = imported
        .bind_whole_program(&source.2, ContentId::of(&source.2))
        .unwrap();
    verify_grouped_metadata(
        &source.0,
        &geometry,
        selected.manifest(),
        &product,
        product.files(),
    )
    .unwrap();
    let marker = b"LI2TOOL-CANDIDATE-UNREADY-V1\0";
    assert_eq!(
        source
            .0
            .windows(marker.len())
            .filter(|b| *b == marker)
            .count(),
        1
    );
    assert_eq!(
        product.files()["candidate.elf"]
            .windows(marker.len())
            .filter(|b| *b == marker)
            .count(),
        2
    );
    for name in [
        "grouping-policy.tsv",
        "binding-policy.tsv",
        "selection.txt",
        "target.tsv",
        "metadata.li2meta",
        "candidate.elf",
        "plan-ledger.tsv",
    ] {
        let mut files = product.files().clone();
        let raw = files.get_mut(name).unwrap();
        let before = raw.clone();
        if name == "candidate.elf" {
            let marker = b"LI2TOOL-CANDIDATE-UNREADY-V1\0";
            let at = raw
                .windows(marker.len())
                .rposition(|b| b == marker)
                .unwrap()
                + marker.len();
            raw[at] ^= 1;
        } else {
            raw.push(b'!');
        }
        assert_ne!(*raw, before);
        assert_eq!(
            verify_grouped_metadata(&source.0, &geometry, selected.manifest(), &product, &files)
                .unwrap_err()
                .stage,
            "grouped-cli-metadata"
        );
    }
    let mut wrong = source.0.clone();
    wrong[0x2fff] ^= 1;
    assert_eq!(
        verify_grouped_metadata(
            &wrong,
            &geometry,
            selected.manifest(),
            &product,
            product.files()
        )
        .unwrap_err()
        .stage,
        "grouped-cli-metadata"
    );
}

// Sibling upstream controls reuse the exact imported fixture/CLI adapter.
pub(super) fn upstream_fixture(chunks: &[&[u8]]) -> (Vec<u8>, Vec<u8>, Vec<u8>) {
    fixture(chunks)
}
pub(super) fn upstream_run(
    source: &(Vec<u8>, Vec<u8>, Vec<u8>),
    mode: PopulationMode,
) -> (
    liteinst_rewrite::Product,
    BTreeMap<String, Vec<u8>>,
    Option<[usize; 3]>,
) {
    run(source, mode)
}

