pub(super) fn storage_fixture() -> (Vec<u8>, Vec<u8>, Vec<u8>) {
    six_pop()
}
pub(super) fn storage_fixture_chunks(chunks: &[&[u8]]) -> (Vec<u8>, Vec<u8>, Vec<u8>) {
    fixture(chunks)
}
